package com.wardk.meeteam_backend.github.webhook;
import com.fasterxml.jackson.databind.*;
import com.wardk.meeteam_backend.domain.github.webhook.*;
import com.wardk.meeteam_backend.domain.github.integration.*;
import com.wardk.meeteam_backend.domain.github.activity.GithubActivityWriter;
import com.wardk.meeteam_backend.domain.github.collaboration.GithubCollaborationService;
import jakarta.persistence.*;
import org.junit.jupiter.api.*;
import java.time.Instant;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class GithubWebhookProcessorTest {
 final EntityManager em=mock(EntityManager.class);final GithubActivityWriter activity=mock(GithubActivityWriter.class);final GithubCollaborationService collaboration=mock(GithubCollaborationService.class);final ObjectMapper mapper=new ObjectMapper();final GithubProjectLink link=new GithubProjectLink(1);GithubWebhookProcessor processor;
 @BeforeEach void setup(){link.setInstallationId(8L);link.setInstallationActive(true);link.setGithubRepositoryId(3L);link.setDefaultBranch("main");link.setAuthorizedRepositoryIds("[3,4]");TypedQuery<GithubProjectLink> query=mock(TypedQuery.class);when(em.createQuery(anyString(),eq(GithubProjectLink.class))).thenReturn(query);when(query.setParameter(anyString(),any())).thenReturn(query);when(query.setLockMode(any())).thenReturn(query);when(query.getResultList()).thenReturn(List.of(link));processor=new GithubWebhookProcessor(em,mapper,activity,collaboration);}
 JsonNode event(String name,String fields)throws Exception{return mapper.readTree("{\"event\":\""+name+"\",\"installation\":{\"id\":8},\"repository\":{\"id\":3},\"received_at\":\"2026-01-01T00:00:00Z\","+fields+"}");}
 @Test void correctlySignedButUnlinkedRepositoryIgnored()throws Exception{JsonNode n=mapper.readTree("{\"event\":\"push\",\"installation\":{\"id\":8},\"repository\":{\"id\":999},\"ref\":\"refs/heads/main\"}");processor.apply(1,n,Map.of());verifyNoInteractions(activity,collaboration);verify(em).persist(any(GithubWebhookReceipt.class));}
 @Test void replayDoesNotRepeatNotificationOrActivity()throws Exception{when(em.find(GithubWebhookReceipt.class,7L)).thenReturn(new GithubWebhookReceipt(7));processor.apply(7,event("pull_request","\"action\":\"closed\",\"pull_request\":{\"number\":5,\"merged\":true,\"user\":{\"id\":9}}"),Map.of());verifyNoInteractions(activity,collaboration);verify(em,never()).persist(any());}
 @Test void featureBranchDoesNotCount()throws Exception{processor.apply(1,event("push","\"ref\":\"refs/heads/feature\",\"commits\":[]"),Map.of());verifyNoInteractions(activity);}
 @Test void commitUsesResolvedAuthorNeverSenderAndPushReceiveTime()throws Exception{String sha="a".repeat(40);processor.apply(1,event("push","\"ref\":\"refs/heads/main\",\"sender\":{\"id\":999},\"head_commit\":{\"timestamp\":\"2026-02-01T00:00:00Z\"},\"commits\":[{\"id\":\""+sha+"\",\"timestamp\":\"2026-01-02T00:00:00Z\"}]"),Map.of(sha,4L));verify(activity).event(3,"commit:"+sha,"COMMIT",4L,null,null,null,Instant.parse("2026-01-02T00:00:00Z"));verify(activity).pushed(3,Instant.parse("2026-01-01T00:00:00Z"));}
 @Test void forcePushOldCommitUsesNewRepositoryPushTime()throws Exception{String sha="b".repeat(40);JsonNode n=event("push","\"ref\":\"refs/heads/main\",\"head_commit\":{\"timestamp\":\"2020-01-01T00:00:00Z\"},\"commits\":[{\"id\":\""+sha+"\",\"timestamp\":\"2020-01-01T00:00:00Z\"}]");((com.fasterxml.jackson.databind.node.ObjectNode)n.path("repository")).put("pushed_at",Instant.parse("2026-04-01T00:00:00Z").getEpochSecond());processor.apply(1,n,Map.of());verify(activity).pushed(3,Instant.parse("2026-04-01T00:00:00Z"));verify(activity).event(3,"commit:"+sha,"COMMIT",null,null,null,null,Instant.parse("2020-01-01T00:00:00Z"));}
 @Test void suspensionClearsBindingButUnsuspendNeverRegrants()throws Exception{processor.apply(1,event("installation","\"action\":\"suspend\""),Map.of());assertFalse(link.isInstallationActive());assertNull(link.getGithubRepositoryId());assertEquals(1,link.getBindingVersion());processor.apply(2,event("installation","\"action\":\"unsuspend\""),Map.of());assertFalse(link.isInstallationActive());}
 @Test void installationRemovalClearsAuthorizedIdsAndBinding()throws Exception{processor.apply(1,event("installation_repositories","\"action\":\"removed\",\"repositories_removed\":[{\"id\":3}]"),Map.of());assertNull(link.getGithubRepositoryId());assertEquals("[4]",link.getAuthorizedRepositoryIds());}
 @Test void stalePublicWebhookCannotUndoKnownPrivate()throws Exception{link.setRepositoryPrivate(true);JsonNode n=mapper.readTree("{\"event\":\"repository\",\"action\":\"publicized\",\"installation\":{\"id\":8},\"repository\":{\"id\":3,\"private\":false}}");processor.apply(1,n,Map.of());assertTrue(link.isRepositoryPrivate());verify(em).lock(link,LockModeType.PESSIMISTIC_FORCE_INCREMENT);verify(activity).requestSync(3);}
 @Test void repeatedPrivateNoopStillFencesConcurrentSync()throws Exception{link.setRepositoryPrivate(true);long binding=link.getBindingVersion();JsonNode n=mapper.readTree("{\"event\":\"repository\",\"action\":\"privatized\",\"installation\":{\"id\":8},\"repository\":{\"id\":3,\"private\":true}}");processor.apply(1,n,Map.of());verify(em).lock(link,LockModeType.PESSIMISTIC_FORCE_INCREMENT);assertEquals(binding,link.getBindingVersion());assertTrue(link.isRepositoryPrivate());}
 @Test void privateEventUpdatesSharedPrivacyBeforeSync()throws Exception{JsonNode n=mapper.readTree("{\"event\":\"repository\",\"action\":\"privatized\",\"installation\":{\"id\":8},\"repository\":{\"id\":3,\"private\":true}}");processor.apply(1,n,Map.of());assertTrue(link.isRepositoryPrivate());verify(activity).requestSync(3);}
}
